
-- CHECK_E192: F8-5 per-domain loosen doors. One row per check, 'OK' or 'FAIL'.
select 'tier mail.tls.loosen is T2 and built' as check, case when exists (select 1 from public.founder_action_tiers where action = 'mail.tls.loosen' and tier = 2 and built) then 'OK' else 'FAIL' end as result
union all select 'the exception table is private (forced RLS, select only)', case when (select relforcerowsecurity from pg_class where oid = 'public.fmail_tls_dom192'::regclass) and not has_table_privilege('service_role', 'public.fmail_tls_dom192', 'insert') and not has_table_privilege('authenticated', 'public.fmail_tls_dom192', 'select') then 'OK' else 'FAIL' end
union all select 'six doors exist for service_role', case when (select count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname in ('fmail_tls_loosen_digest192', 'fmail_tls_loosen_apply192', 'fmail_tls_dom_tighten192', 'fmail_tls_dom_loose192', 'fmail_tls_dom_heal192', 'fmail_tls_state192') and has_function_privilege('service_role', p.oid, 'execute')) = 6 then 'OK' else 'FAIL' end
union all select 'helpers are closed to every API role', case when not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname in ('_tls_loosen_params192', '_tls_loosen_dry192') and (has_function_privilege('anon', p.oid, 'execute') or has_function_privilege('authenticated', p.oid, 'execute') or has_function_privilege('service_role', p.oid, 'execute'))) then 'OK' else 'FAIL' end
union all select 'E179 door audit still clean', case when not exists (select 1 from public.fmail_door_audit179()) then 'OK' else 'FAIL' end
union all select 'selftest ' || coalesce(((public.fmail_selftest192() ->> 'passed') || '/' || (public.fmail_selftest192() ->> 'total')), 'none') || coalesce(' ' || nullif((select string_agg(e ->> 'name', '; ') from jsonb_array_elements(public.fmail_selftest192() -> 'checks') e where (e ->> 'ok') <> 'true'), ''), ''),
       case when (public.fmail_selftest192() ->> 'ok') = 'true' then 'OK' else 'FAIL' end;
